import { RouterLinkStub, mount } from '@vue/test-utils'
import { describe, expect, it } from 'vitest'

import SideNav from '@/components/layout/SideNav.vue'
import type { SystemCapabilities, User } from '@/types'

const user: User = {
  id: '11111111-1111-4111-8111-111111111111',
  email: 'you@example.com',
  display_name: '周丹',
  status: 'active',
  role: 'user',
  created_at: '2026-10-01T08:00:00Z',
  last_login_at: '2026-11-09T08:00:00Z',
}

function mountNav(capabilities?: SystemCapabilities): ReturnType<typeof mount> {
  return mount(SideNav, {
    props: {
      collapsed: false,
      mobile: false,
      open: false,
      user,
      theme: 'light',
      capabilities,
    },
    global: {
      stubs: {
        RouterLink: RouterLinkStub,
        AccountMenu: true,
      },
    },
  })
}

describe('SideNav', () => {
  it('渲染六个一级导航与目标路由', () => {
    const wrapper = mountNav()
    const links = wrapper.findAllComponents(RouterLinkStub)

    expect(links).toHaveLength(6)
    expect(links.map((link) => link.text())).toEqual(['对话', '审批', '工作流', '智能体', '任务', '知识库'])
    expect(links.map((link) => link.props('to'))).toEqual([
      { name: 'chat' },
      { name: 'approvals' },
      { name: 'workflows' },
      { name: 'agents' },
      { name: 'tasks' },
      { name: 'knowledge' },
    ])
  })

  it('折叠时仍保留可访问的导航标题', () => {
    const wrapper = mountNav()
    const links = wrapper.findAllComponents(RouterLinkStub)
    expect(links[0]?.attributes('title')).toBe('对话')
    expect(links[5]?.attributes('title')).toBe('知识库')
  })

  it('账号菜单点击诊断信息时向父级透传 diagnostics 事件', async () => {
    const wrapper = mount(SideNav, {
      props: {
        collapsed: false,
        mobile: false,
        open: false,
        user,
        theme: 'light',
      },
      global: {
        stubs: { RouterLink: RouterLinkStub },
      },
    })

    await wrapper.get('button.account').trigger('click')
    const item = wrapper
      .findAll('button.menu-item')
      .find((button) => button.text().includes('诊断信息'))
    expect(item).toBeTruthy()

    await item!.trigger('click')

